"""Manuscript content (revision v2). Inline markup: *italic*, **bold**, _{sub}, ^{sup}. Citations: {key} or {k1,k2}."""
import json, re

TITLE = "False-Alarm Control and Explanation Reliability of Feature-Token Transformers for Network Intrusion Detection under Dataset Shift"
AUTHOR = "Xinghui Wu"
AFFIL = "School of Computer Science, University of Birmingham, Birmingham B15 2TT, UK; [e-mail address]"

ABSTRACT = ("Transformer-based network intrusion detection systems (NIDSs) are usually reported at a default decision threshold and with single-run explanations, so their false-alarm behaviour and the reliability of their explanations remain unclear. "
 "This study evaluates a feature-token Transformer (FTT-IDS) against random forest, XGBoost, MLP, 1D-CNN and FT-Transformer baselines on UNSW-NB15 and TON_IoT under a leakage-controlled protocol: exact duplicates (38.6% and 55.6% of the source files) are removed before splitting, all selection uses validation data only, and every configuration is trained with five seeds. "
 "FTT-IDS matches but does not exceed gradient-boosted trees (ROC-AUC 0.984; detection rate at a 1% test false-positive rate 85.6% versus 86.2% for XGBoost). "
 "The decision rule matters more than the model: fixing the threshold at a 1% validation false-alarm budget lowers the UNSW-NB15 test false-positive rate from 26.6% to 4.4% and raises F1 from 89.5% to 93.7%, for every model and on de-duplicated test data. "
 "The budget is nevertheless exceeded about fourfold because of a train–test shift; recalibrating the threshold on 1000 benign flows from the target network restores it (1.1%) at 85.9% recall. "
 "Expected-gradients SHAP rankings are faithful at the global level but only moderately stable across retrained models (Spearman 0.76). They trace the false alarms to TTL features, yet removing these features leaves the false alarms unchanged, which identifies them as proxies for the shift. "
 "Operating-point false-alarm rates and explanation reliability should therefore be reported alongside accuracy.")
KEYWORDS = "network intrusion detection; Transformer; explainable artificial intelligence; SHAP; false alarms; decision threshold; dataset shift; UNSW-NB15; TON_IoT; Internet of Things security"

B = []  # blocks
